package com.sathavahana.kalamkari.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Entity @Table(name="orders") public class Order { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) private User user; @Enumerated(EnumType.STRING) private Status status=Status.PENDING; @Column(name="payment_status") private String paymentStatus="PENDING"; @Column(name="total_amount") private BigDecimal totalAmount=BigDecimal.ZERO; @OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true) private List<OrderItem> items=new ArrayList<>(); @Column(name="created_at") private Instant createdAt=Instant.now(); public enum Status{PENDING,CONFIRMED,SHIPPED,DELIVERED,CANCELLED} public Order(){} public Order(User u){user=u;} public Long getId(){return id;} public User getUser(){return user;} public List<OrderItem> getItems(){return items;} public Status getStatus(){return status;} public void setStatus(Status v){status=v;} public String getPaymentStatus(){return paymentStatus;} public void setPaymentStatus(String v){paymentStatus=v;} public BigDecimal getTotalAmount(){return totalAmount;} public void setTotalAmount(BigDecimal v){totalAmount=v;} public Instant getCreatedAt(){return createdAt;}}
